import React from 'react';
import { Document, Page, pdfjs } from 'react-pdf';

// PDFs
import beneficiaryList from '../assets/ICICIBankRTGSNEFTDemo/Beneficiary List.pdf';
import remitterList from '../assets/ICICIBankRTGSNEFTDemo/Remitter List.pdf';
import fillDetails from '../assets/ICICIBankRTGSNEFTDemo/Fill Details.pdf';
import stepsToUse from '../assets/ICICIBankRTGSNEFTDemo/Steps to use the file.pdf';
import formPage1 from '../assets/ICICIBankRTGSNEFTDemo/Form 1 Page.pdf';
import formPage2 from '../assets/ICICIBankRTGSNEFTDemo/Form 2 Page.pdf';
import chequePrint from '../assets/ICICIBankRTGSNEFTDemo/cheque print.png';
import excelFile from '../assets/ICICIBankRTGSNEFTDemo/ICICI Bank RTGS NEFT Application Form New Upload.xlsm';

// Set up worker
pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;

const PdfPreview = ({ file }) => (
  <div style={{ marginBottom: '10px', borderRadius: '10px', overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
    <Document file={file}>
      <Page pageNumber={1} width={500} />
    </Document>
  </div>
);

const styles = {
  container: {
    padding: '40px 20px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: 'Segoe UI, sans-serif',
    color: '#2c3e50'
  },
  title: {
    textAlign: 'center',
    fontSize: '2.5rem',
    fontWeight: 600,
    marginBottom: '20px'
  },
  subtitle: {
    textAlign: 'center',
    fontSize: '1.2rem',
    marginBottom: '40px',
    color: '#555'
  },
  section: {
    marginBottom: '40px'
  },
  sectionTitle: {
    fontSize: '1.5rem',
    fontWeight: 500,
    marginBottom: '10px',
    borderBottom: '2px solid #3498db',
    paddingBottom: '5px'
  },
  list: {
    listStyle: 'disc',
    paddingLeft: '20px',
    color: '#333'
  },
  downloadLink: {
    display: 'inline-block',
    backgroundColor: '#3498db',
    color: 'white',
    padding: '10px 20px',
    marginTop: '10px',
    marginRight: '10px',
    borderRadius: '6px',
    textDecoration: 'none',
    transition: 'background-color 0.3s ease'
  },
  previewImg: {
    width: '100%',
    maxWidth: '500px',
    marginBottom: '10px',
    borderRadius: '10px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.15)'
  },
  fileGroup: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'start',
    marginTop: '20px',
    gap: '20px'
  }
};

const ICICI = () => {
  return (
    <div style={styles.container}>
      <h1 style={styles.title}>ICICI Bank RTGS/NEFT Form Utility</h1>
      <p style={styles.subtitle}>Generate, customize, and print your ICICI RTGS/NEFT form with ease.</p>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>📄 Sample Form Pages</h2>
        <div style={styles.fileGroup}>
          <div>
            <PdfPreview file={formPage1} />
            <a href={formPage1} download style={styles.downloadLink}>Download Form Page 1</a>
          </div>
          <div>
            <PdfPreview file={formPage2} />
            <a href={formPage2} download style={styles.downloadLink}>Download Form Page 2</a>
          </div>
        </div>
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>🖨️ Cheque Print Sample</h2>
        <img src={chequePrint} alt="Cheque Print Sample" style={styles.previewImg} />
        <a href={chequePrint} download style={styles.downloadLink}>Download Cheque Sample</a>
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>📁 Instructional PDFs</h2>
        <div style={styles.fileGroup}>
          <div>
            <PdfPreview file={fillDetails} />
            <a href={fillDetails} download style={styles.downloadLink}>Download Fill Details</a>
          </div>
          <div>
            <PdfPreview file={stepsToUse} />
            <a href={stepsToUse} download style={styles.downloadLink}>Download Steps to Use</a>
          </div>
        </div>
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>👥 Sample Data Files</h2>
        <div style={styles.fileGroup}>
          <div>
            <PdfPreview file={beneficiaryList} />
            <a href={beneficiaryList} download style={styles.downloadLink}>Download Beneficiary List</a>
          </div>
          <div>
            <PdfPreview file={remitterList} />
            <a href={remitterList} download style={styles.downloadLink}>Download Remitter List</a>
          </div>
        </div>
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>📊 Excel Tool</h2>
        <a href={excelFile} download style={styles.downloadLink}>Download Excel Generator Tool</a>
      </div>
    </div>
  );
};

export default ICICI;
